import numpy as np

def sigmoid(z): return 1/(1+np.exp(-z))
def loss(x): return np.logaddexp(0, 3*np.sin(x)-1)
def chain_rule(x):
    z=3*np.sin(x)-1
    return sigmoid(z)*3*np.cos(x)

for x in [-1.0, .2, 1.3]:
    h=1e-5; numeric=(loss(x+h)-loss(x-h))/(2*h)
    print(f"x={x:+.1f}: chain={chain_rule(x):+.8f}, numeric={numeric:+.8f}")
print("sensitivity through 20 layers:", 0.5**20)

